{
  "scenario_title": "Clinical trial budget burn rates and milestone tracking across global CRO vendors and studies, 2022-2024",
  "data_context": "A global biopharmaceutical sponsor's clinical finance operations team compiled monthly cost and delivery records across active outsourced trials between January 2022 and June 2024 to evaluate contract research organization (CRO) burn efficiency and budget variance against critical study milestones.",
  "script": "dim(\"cro_vendor\", [\"IQVIA\", \"Icon plc\", \"Parexel\", \"Syneos Health\"], weights=[0.35, 0.28, 0.22, 0.15], group=\"operations\")\ndim(\"study_code\", [\"ONCO-Phase3\", \"IMM-Phase2\", \"NEURO-Phase1\", \"CARD-Phase3\", \"RARE-Phase2\"], parent=\"cro_vendor\", weights={\"IQVIA\": [0.45, 0.35, 0.00, 0.20, 0.00], \"Icon plc\": [0.00, 0.30, 0.40, 0.30, 0.00], \"Parexel\": [0.35, 0.00, 0.00, 0.40, 0.25], \"Syneos Health\": [0.00, 0.20, 0.30, 0.00, 0.50]}, group=\"operations\")\ndim(\"cost_category\", [\"Site Payments\", \"CRO Operational Fees\", \"Patient Recruitment\", \"Lab & Diagnostics\", \"Regulatory & Safety\"], weights=[0.30, 0.25, 0.20, 0.15, 0.10], group=\"finance\")\ndim(\"milestone_phase\", [\"Study Startup\", \"Active Recruitment\", \"Treatment & Follow-up\", \"Study Closeout\"], weights=[0.20, 0.45, 0.25, 0.10], ordered=\"stage\", group=\"milestone\")\n\ntime(\"report_date\", start=\"2022-01-01\", end=\"2024-06-30\", freq=\"monthly\")\n\nmeasure(\"monthly_spend\", \"gamma(shape=5, scale=8) + {\\\"Site Payments\\\": 65, \\\"CRO Operational Fees\\\": 50, \\\"Patient Recruitment\\\": 35, \\\"Lab & Diagnostics\\\": 25, \\\"Regulatory & Safety\\\": 15}[cost_category] * (1.0 + 0.0004 * report_date) + {\\\"ONCO-Phase3\\\": 30, \\\"IMM-Phase2\\\": 15, \\\"NEURO-Phase1\\\": 5, \\\"CARD-Phase3\\\": 25, \\\"RARE-Phase2\\\": 10}[study_code]\", unit=\"USD thousands\", additive=True)\nmeasure(\"enrolled_patients\", \"poisson(lam=12 + 8 * [milestone_phase=Active Recruitment] + 4 * [cost_category=Patient Recruitment] - 6 * [milestone_phase=Study Closeout])\", unit=\"patients\", additive=True)\nmeasure(\"cost_per_patient\", \"clip((monthly_spend * 1000) / clip(enrolled_patients, 1, 50) + gaussian(0, 200), 800, 18000)\", unit=\"USD\", additive=False)\nmeasure(\"milestone_completion_rate\", \"clip(beta(2.5, 2.0) * 100 + {\\\"Study Startup\\\": -20, \\\"Active Recruitment\\\": 5, \\\"Treatment & Follow-up\\\": 25, \\\"Study Closeout\\\": 40}[milestone_phase] + 0.05 * monthly_spend, 5.0, 100.0)\", unit=\"percent\", additive=False)\n\nemit(750)",
  "intents": [
    {
      "sentence": "Total spend breakdown by cost category across CRO vendors",
      "columns": [
        "cro_vendor",
        "cost_category",
        "monthly_spend"
      ],
      "aggregate": "SUM",
      "family": "composition"
    },
    {
      "sentence": "Monthly spend trajectory across the multi-year trial duration",
      "columns": [
        "report_date",
        "monthly_spend"
      ],
      "aggregate": "SUM",
      "family": "trend"
    },
    {
      "sentence": "Relationship between monthly spend and milestone completion rate",
      "columns": [
        "monthly_spend",
        "milestone_completion_rate"
      ],
      "aggregate": "NONE",
      "family": "relation"
    },
    {
      "sentence": "Average cost per enrolled patient across trial milestone phases",
      "columns": [
        "milestone_phase",
        "cost_per_patient"
      ],
      "aggregate": "AVG",
      "family": "comparison"
    }
  ]
}
